from pathlib import Path
p=Path('tests/cli_t18a.rs');s=p.read_text(encoding='utf-8');s=s[:s.index('\n\n\nfn fixture()')];s=s.replace('Temp/T16-B-tooling/tests','Temp/T18-B-tooling/cli-tests');Path('tests/cli_t18b.rs').write_text(s+'''
fn call(url:&str)->String{format!("httpRequest(\\"GET\\",{url:?},[],\\"\\",2000,4096)")}
#[test]fn permission_is_independent_and_no_connection_on_validation_failure(){let w=Work::new();let s=call("http://127.0.0.1:1/");for flags in [vec![],vec!["--allow-process"]]{let mut a=flags;a.extend(["-e",&s,"--json"]);let r=w.run(&a,b"");assert_eq!(r.status.code(),Some(2));assert!(String::from_utf8_lossy(&r.stdout).contains("HTTP 能力未启用"),"{r:?}");}let code="exec([\\"C:\\\\not-present.exe\\"],10,0)";let r=w.run(&["--allow-http","-e",code,"--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("子进程能力未启用"));let r=w.run(&["--allow-http","-e","httpRequest(\\"get\\",\\"http://127.0.0.1:1/\\",[],\\"\\",1,0)","--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("HTTP method 不受支持"));}
#[test]fn strict_cli_scan_and_protected_code_argv(){let w=Work::new();for cmd in ["check","test","--help","-h","--version","-V"]{let r=w.run(&[cmd,"--allow-http"],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains("HTTP 能力选项只适用于运行命令"));}for (a,message) in [(vec!["--allow-http","--allow-http","-e",""],"不能重复"),(vec!["--help","--allow-http="],"不接受值"),(vec!["check","--allow-http","--max-steps","x"],"值必须")]{let r=w.run(&a,b"");assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains(message));}for (flags,message) in [(vec!["--allow-http","--allow-process"],"HTTP 能力"),(vec!["--allow-process","--allow-http"],"子进程能力"),(vec!["--max-steps","1","--allow-http"],"执行限额")]{let mut a=vec!["check"];a.extend(flags);let r=w.run(&a,b"");assert!(String::from_utf8_lossy(&r.stderr).contains(message));}let r=w.run(&["-e","print(argv()[0])","--","--allow-http"],b"");assert_eq!(r.stdout,b"--allow-http\\n");let r=w.run(&["check","-e","--allow-http","--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("\\"mode\\":\\"check\\""));}
#[test]fn module_diagnostic_has_real_source_and_defaults_disabled(){let w=Work::new();w.file("dep.lfz",&format!("fn go()=>{}\\nexport go",call("http://127.0.0.1:1/")));let p=w.file("root.lfz","import d from \\"./dep.lfz\\"\\nd.go()");let r=w.run(&["run",&p,"--json"],b"");assert_eq!(r.status.code(),Some(2));let out=String::from_utf8(r.stdout).unwrap();assert!(out.contains("HTTP 能力未启用")&&out.contains("dep.lfz"),"{out}");}
''',encoding='utf-8')
